-- hejmo:foreign-keys-off
-- Shared meal plan (ADR 0015) and its cut-off times (ADR 0016).

-- The meal plan is shown in the calendar as a calendar generated by the box:
-- kind 'meals'. SQLite cannot change a CHECK constraint, so the table is
-- rebuilt (the marker above runs this migration with foreign keys off, so the
-- drop does not cascade into events and sync state).
CREATE TABLE calendars_new (
    id            TEXT PRIMARY KEY,
    household_id  TEXT NOT NULL REFERENCES households(id) ON DELETE CASCADE,
    name          TEXT NOT NULL,
    kind          TEXT NOT NULL CHECK (kind IN ('local', 'ics', 'caldav', 'google', 'meals')),
    color         TEXT NOT NULL DEFAULT '',
    created_at    TEXT NOT NULL,
    updated_at    TEXT NOT NULL,
    connection_id TEXT REFERENCES calendar_connections(id) ON DELETE CASCADE,
    read_only     INTEGER NOT NULL DEFAULT 0,
    shared        INTEGER NOT NULL DEFAULT 0,
    remote_url    TEXT
);
INSERT INTO calendars_new (rowid, id, household_id, name, kind, color, created_at, updated_at, connection_id, read_only, shared, remote_url)
    SELECT rowid, id, household_id, name, kind, color, created_at, updated_at, connection_id, read_only, shared, remote_url FROM calendars;
DROP TABLE calendars;
ALTER TABLE calendars_new RENAME TO calendars;
CREATE UNIQUE INDEX calendars_remote_url ON calendars (connection_id, remote_url) WHERE remote_url IS NOT NULL;

-- One free-text entry per day and mealtime. Each entry has one all-day event in
-- the household's meal calendar; the event is written whenever the entry is.
CREATE TABLE meal_plan (
    household_id TEXT NOT NULL REFERENCES households(id) ON DELETE CASCADE,
    day          TEXT NOT NULL,                  -- 'YYYY-MM-DD'
    mealtime     TEXT NOT NULL CHECK (mealtime IN ('breakfast', 'lunch', 'snack', 'dinner')),
    text         TEXT NOT NULL,
    event_id     TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE,
    updated_at   TEXT NOT NULL,
    PRIMARY KEY (household_id, day, mealtime)
);

-- Time of day ('HH:MM') from which a mealtime is no longer shown on displays;
-- empty = no cut-off, shown for the rest of the day.
ALTER TABLE households ADD COLUMN cutoff_breakfast TEXT NOT NULL DEFAULT '10:00';
ALTER TABLE households ADD COLUMN cutoff_lunch TEXT NOT NULL DEFAULT '13:30';
ALTER TABLE households ADD COLUMN cutoff_snack TEXT NOT NULL DEFAULT '16:30';
ALTER TABLE households ADD COLUMN cutoff_dinner TEXT NOT NULL DEFAULT '';
